// src/data/soundWordBuilderData.ts
// Comprehensive Sound-to-Word (2 to 15 letters) & Sound-to-Sentence with Parts of Speech Analysis

export interface SoundWordItem {
  id: string;
  word: string;
  lettersCount: number; // 2 to 15
  letters: string[];
  emoji: string;
  meaningHindi: string;
  pronunciationHindi: string;
  syllables: string[]; // e.g. ['con', 'grat', 'u', 'la', 'tion']
  soundRuleTitleEn: string;
  soundRuleTitleHi: string;
  soundRuleEnglish: string;
  soundRuleHindi: string;
  exampleSoundTip: string;
}

export interface SoundSpellingRule {
  id: string;
  ruleNumber: number;
  titleEnglish: string;
  titleHindi: string;
  emoji: string;
  formula: string;
  explanationEnglish: string;
  explanationHindi: string;
  examples: { word: string; meaningHindi: string; breakdown: string }[];
  audioTipEnglish: string;
  audioTipHindi: string;
}

export interface SentenceWordToken {
  word: string;
  partOfSpeech: 'noun' | 'pronoun' | 'verb' | 'helping-verb' | 'modal-verb' | 'adjective' | 'preposition' | 'article' | 'conjunction' | 'adverb';
  posLabelEnglish: string;
  posLabelHindi: string;
  roleExplanationHindi: string;
  colorBg: string;
  colorText: string;
  colorBorder: string;
  emoji: string;
}

export type SentenceCategory = 'all' | 'present' | 'past' | 'future' | 'modals';

export interface SoundSentenceItem {
  id: string;
  category: 'present' | 'past' | 'future' | 'modals';
  fullSentenceEnglish: string;
  fullSentenceHindi: string;
  emoji: string;
  tokens: SentenceWordToken[];
  tenseType: string;
  tenseLabelEnglish: string;
  tenseLabelHindi: string;
  dailyContextHindi: string; // e.g. "रोज़ की आदत (Daily Routine)"
  formulaPattern?: string;
}

